practice.solutionCode:
// Day 41: 객체지향 모델링: 핵심 원리와 내부 동작 예시 풀이
import java.util.List;

public class Main {
    static int solveDay41(List<Integer> values) {
        return values.stream().filter(value -> value % 2 == 1).mapToInt(Integer::intValue).sum();
    }

    public static void main(String[] args) {
        System.out.println("객체지향 모델링: 핵심 원리와 내부 동작");
        System.out.println(solveDay41(List.of(1, 2, 3, 4)));
    }
}

